?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($category['title'] ?? 'Room category') ?> rooms — Cox Booking</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700&family=Noto+Serif+Bengali:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="bengali-ui.css"><link rel="stylesheet" href="pages.css"><link rel="stylesheet" href="responsive.css"><link rel="stylesheet" href="rooms.css?v=5"></head><body><?php include 'partials.php'; ?><main><section class="rooms-heading wrap"><a class="back-link" href="index.php#room-categories">← Room categories</a><div class="eyebrow"><span></span> Browse rooms</div><h1><?=e($category['title'] ?? 'Room categories')?></h1><p><?= $category ? count($categoryRooms) . ' rooms · ' . e($category['location']) : 'This room category is not available.' ?></p></section><section class="wrap room-list-grid"><?php foreach ($categoryRooms as $room): ?><a class="room-list-card" href="room.php?id=<?=rawurlencode($room['public_id'])?>"><div class="room-list-photo"><img src="<?=e(roomPhoto($room['images'][0],1000))?>" alt="<?=e($room['name'])?>"><span>View room <b>↗</b></span></div><div class="room-list-info"><div><h2><?=e($room['name'])?></h2><p><?=e($room['location'])?></p></div><p class="room-list-price">From <b><?=e($room['price'])?></b> <small>/ night</small></p></div><div class="room-list-amenities"><?php foreach ($room['amenities'] as $amenity): ?><span><?=e($amenity)?></span><?php endforeach; ?></div></a><?php endforeach; ?><?php if($category && !$categoryRooms): ?><p>No rooms are listed in this category yet.</p><?php endif; ?></section></main><?php include 'footer.php'; ?></body></html>
